import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.D1JEzK2q.js";const u=JSON.parse('{"title":"Agents and sessions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agents.md","filePath":"guide/agents.md"}'),n={name:"guide/agents.md"};function r(i,e,d,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="agents-and-sessions" tabindex="-1">Agents and sessions <a class="header-anchor" href="#agents-and-sessions" aria-label="Permalink to &quot;Agents and sessions&quot;">​</a></h1><p>An <strong>agent</strong> owns a workspace, identity, model configuration, and channel connections. A <strong>session</strong> is one conversation&#39;s model context. Multiple agents can share one gateway while keeping their sessions separate.</p><h2 id="define-an-agent" tabindex="-1">Define an agent <a class="header-anchor" href="#define-an-agent" aria-label="Permalink to &quot;Define an agent&quot;">​</a></h2><p>Create an agent with <code>claude-gateway agents create</code>, then edit its source workspace files:</p><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>AGENTS.md</code></td><td>Required core instructions and capabilities</td></tr><tr><td><code>IDENTITY.md</code></td><td>Name, emoji, avatar, identity</td></tr><tr><td><code>SOUL.md</code></td><td>Tone and speaking style</td></tr><tr><td><code>USER.md</code></td><td>User preferences</td></tr><tr><td><code>MEMORY.md</code></td><td>Long-term core memory</td></tr><tr><td><code>HEARTBEAT.md</code></td><td>Proactive schedules</td></tr><tr><td><code>skills/</code></td><td>Agent-specific reusable skills</td></tr></tbody></table><p>For example, an <code>AGENTS.md</code> can begin:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">You are a personal research assistant.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Explain your findings clearly and link to the sources you used.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Before changing a file, read its existing content.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Report what you verified and what remains uncertain.</span></span></code></pre></div><p>The gateway assembles workspace files into <code>CLAUDE.md</code> on startup and file changes. Edit the source files, then ask the agent to describe its role to verify the update. Avoid editing the generated <code>CLAUDE.md</code>.</p><h2 id="manage-a-conversation" tabindex="-1">Manage a conversation <a class="header-anchor" href="#manage-a-conversation" aria-label="Permalink to &quot;Manage a conversation&quot;">​</a></h2><p>In a paired Telegram private chat, <code>/session</code> shows the current session, <code>/sessions</code> switches between sessions, and <code>/new &lt;name&gt;</code> starts a new one. <code>/compact</code> summarizes context. <code>/stop</code> interrupts the current turn. <code>/restart</code> restarts a session after confirmation.</p><p>Changing the agent&#39;s model affects all its sessions. Use <code>/models</code> and confirm the choice in a private chat. Chat history and the model&#39;s active context are separate: compacting context does not mean the persistent history database has been erased.</p><h2 id="tune-capacity" tabindex="-1">Tune capacity <a class="header-anchor" href="#tune-capacity" aria-label="Permalink to &quot;Tune capacity&quot;">​</a></h2><p><code>agents[].session.idleTimeoutMinutes</code> controls idle session eviction; <code>maxConcurrent</code> controls legacy concurrent sessions (the template uses 30 minutes and 20 sessions). These are different from worker task limits in <a href="./orchestration.html">orchestration</a>.</p><p>Source: <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/agent/workspace-loader.ts" target="_blank" rel="noreferrer">workspace composition</a> and <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/session/store.ts" target="_blank" rel="noreferrer">session persistence</a>.</p><h2 id="what-belongs-to-an-agent-and-what-belongs-to-a-session" tabindex="-1">What belongs to an agent and what belongs to a session <a class="header-anchor" href="#what-belongs-to-an-agent-and-what-belongs-to-a-session" aria-label="Permalink to &quot;What belongs to an agent and what belongs to a session&quot;">​</a></h2><p>An agent&#39;s workspace is the durable source of its instructions and memory. A session holds the conversation context needed to continue one thread. Starting another session gives the model a fresh conversation while retaining access to the same agent workspace, skills, and searchable memory.</p><table tabindex="0"><thead><tr><th>Change</th><th>Scope</th><th>What to verify</th></tr></thead><tbody><tr><td>Edit <code>SOUL.md</code> or <code>USER.md</code></td><td>Agent workspace</td><td>Generated instructions and a newly spawned session</td></tr><tr><td>Create or switch a session</td><td>One conversation</td><td>Session identifier and selected agent</td></tr><tr><td>Change the agent model</td><td>Agent configuration</td><td>Model shown for subsequent session work</td></tr><tr><td>Compact context</td><td>Active model context</td><td>Continued conversation and persistent history</td></tr><tr><td>Change shared knowledge</td><td>Agents using the same shared project</td><td>Retrieval source and project configuration</td></tr></tbody></table><p>Use separate workspaces for agents with different roles. The startup isolation guard rejects reused workspace paths and Telegram bot tokens; it also checks explicitly configured session directories. This prevents accidental context/configuration overlap. Host agents still execute with the gateway user&#39;s operating-system access, so a separate workspace is not a filesystem sandbox. Container-backed App Store agents have additional runtime boundaries described in <a href="./apps.html">Apps</a>.</p><p>Source: <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/agent/context-isolation.ts" target="_blank" rel="noreferrer">context isolation guard</a>.</p><h2 id="workspace-updates-and-context-size" tabindex="-1">Workspace updates and context size <a class="header-anchor" href="#workspace-updates-and-context-size" aria-label="Permalink to &quot;Workspace updates and context size&quot;">​</a></h2><p>Workspace composition puts role, identity, style, user preferences, memory, and the skill menu into the generated instructions. Keep these files focused: the loader has a hard per-file limit of 20,000 characters and a total limit of 150,000 characters. Memory has smaller soft budgets and can be represented by a section index; see <a href="./memory.html">Memory and knowledge</a>.</p><p>Do not assume an already running model process has reread the files merely because the generated file changed. Instructions are composed for session spawning, and reload/restart handling can defer changes while work is active. Verify an instruction update with a newly spawned session. For a memory lookup, explicitly ask the agent to read the relevant file or use memory retrieval.</p><p>A useful workspace maintenance flow is:</p><ol><li>Read the source file and edit the smallest relevant section.</li><li>Check the generated <code>CLAUDE.md</code> for the intended text and any truncation or budget banner.</li><li>Start a new session and ask a question that depends on the change.</li><li>Confirm both the answer and the selected agent, especially when several bots have similar names.</li></ol><p>Source: <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/agent/workspace-loader.ts" target="_blank" rel="noreferrer">workspace loader</a> and <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/agent/runner.ts" target="_blank" rel="noreferrer">agent runner reload handling</a>.</p><h2 id="claude-code-as-conversational-agent-and-task-worker" tabindex="-1">Claude Code as conversational agent and task worker <a class="header-anchor" href="#claude-code-as-conversational-agent-and-task-worker" aria-label="Permalink to &quot;Claude Code as conversational agent and task worker&quot;">​</a></h2><p>The gateway runs Claude Code in two operating roles when <code>gateway.orchestration</code> is enabled. The user-facing agent retains the workspace identity and conversation, interprets requests, records execution tasks, answers status questions, and summarizes results. A worker runs Claude Code for an assigned task with its own execution profile, session identity, working directory, and permitted tool inventory.</p><p>The conversational role receives scoped task and memory tools. File edits, browser/connector operations, research, and other execution belong to workers. The agent can inspect an attached image directly when answering a visual question; editing or generating media becomes execution work. Workers report through task tools and stage files for delivery instead of sending directly to channels or spawning additional workers.</p><p>For ordinary users, this remains one assistant doing their work. For operators, the separation makes acceptance, queuing, running, failure, and completion independently inspectable. An acknowledgement is not completion; use the persisted task state and verification evidence. Follow-up constraints can update an existing task, while dependent steps use continuations. See <a href="./orchestration.html">Orchestration</a> for task controls and delivery.</p><p>The enable switch is gateway-wide and applies to all supported channels. Per-agent orchestration settings tune conversation/task limits but do not provide independent enable/channel switches. Voice is configured on the agent separately; see <a href="./voice.html">Voice</a>.</p><p>Source: <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/session/runtime-profile.ts" target="_blank" rel="noreferrer">runtime roles</a> and <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/orchestration/gateway-config.ts" target="_blank" rel="noreferrer">gateway mode resolution</a>.</p><h2 id="worker-workspaces-and-capacity" tabindex="-1">Worker workspaces and capacity <a class="header-anchor" href="#worker-workspaces-and-capacity" aria-label="Permalink to &quot;Worker workspaces and capacity&quot;">​</a></h2><p>The default worker mode is <code>host</code>, starting in the agent workspace unless <code>tasks.projectRoot</code> specifies another absolute path. A Git repository is not required for host tasks. Host execution can use other user-authorized paths, so the task&#39;s working directory is not an operating-system access boundary.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Workspace behavior</th><th>Use case</th></tr></thead><tbody><tr><td><code>host</code></td><td>Existing host directory</td><td>General authorized work with native Claude tools</td></tr><tr><td><code>isolated-worktree</code></td><td>Detached Git worktree created for the task</td><td>Independent repository edits with a recorded base commit</td></tr><tr><td><code>shared-lock</code></td><td>Shared project with serialized access and snapshots</td><td>Work that must use one project directory</td></tr><tr><td><code>container</code></td><td>App agent&#39;s validated container workspace</td><td>App-contained execution</td></tr></tbody></table><p>A shared-lock project must differ from, and not contain or sit inside, the agent identity workspace. App agents require container mode and never fall back to host execution. Resource failures can leave a worktree needing reconciliation so potentially useful edits are preserved.</p><p>Defaults allow ten concurrent tasks per agent and per conversation, with queue ceilings of 100 per agent and 20 per conversation. The worker idle timeout is five minutes; <code>maxDurationMs: 0</code> disables the optional total deadline. Idle workers can be retained for ten minutes for reuse. Gateway process limits default to 32 total processes with two slots reserved for conversational agent work. Queue limits, active process limits, and idle retention describe different resources; raising one does not raise the others.</p><p>A task&#39;s explicit model overrides the agent model for that worker. Runtime profiles require empty <code>claude.extraFlags</code>; configure the supported model field instead of bypassing profile construction with custom flags.</p><p>Source: <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/orchestration/config.ts" target="_blank" rel="noreferrer">worker defaults</a>, <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/orchestration/tasks/workspace.ts" target="_blank" rel="noreferrer">workspace preparation</a>, <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/orchestration/tasks/driver.ts" target="_blank" rel="noreferrer">worker driver</a>, and <a href="https://github.com/0xMaxMa/claude-gateway/blob/b917843/src/orchestration/capacity.ts" target="_blank" rel="noreferrer">process capacity</a>.</p>`,38)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
